content.solution_code:
class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `Casting ${this.name}. It costs ${this.manaCost} mana.`;
  }
}

class FireballSpell extends Spell {
  constructor(manaCost, damage) {
    super("Fireball", manaCost);
    this.damage = damage;
  }

  cast() {
    return `Casting ${this.name}! Deals ${this.damage} damage for ${this.manaCost} mana.`;
  }
}

class HealSpell extends Spell {
  constructor(manaCost, healAmount) {
    super("Heal", manaCost);
    this.healAmount = healAmount;
  }

  cast() {
    return `Casting ${this.name}! Restores ${this.healAmount} health for ${this.manaCost} mana.`;
  }
}

